INSERT INTO public."modules" ("id", "course_id", "module_no", "title", "description", "pressure_points", "user_confusion", "industry_challenge", "prerequisites", "what_youll_learn", "when_to_apply", "learning_content", "support", "knowledge", "module_problem_statement", "tools", "is_published", "is_active")
VALUES ('2e018b03-2663-5f67-8e6f-d1327b2894e2'::uuid, '0a010796-10c0-5287-b89a-6ab56bd71399'::uuid, 0, 'Industry, Role & Course Readiness', 'Learner connects front-office arrival readiness to guest trust, room flow, payment/readiness safety, team workload, and L1 role boundaries before working the case.', NULL, NULL, NULL, NULL, NULL, NULL, '["Learn why arrival-readiness checks protect service quality and access safety.", "Compare safe vs unsafe beginner assumptions in a front-office moment.", "Fill Course Readiness Sheet using evidence labels and role-boundary prompts.", "Submit readiness sheet with risk, evidence source, boundary, and validation question."]'::jsonb, '["List the five arrival-readiness evidence sources and mark one open validation question before entering Module 1.", "Write one evidence-before-action sentence for the Course Readiness Sheet.", "Classify three actions as allowed / not allowed / escalation required.", "Ask boundary-check questions, simplify SOP language, and help the learner compare safe vs unsafe first moves after the learner writes one human observation and one open validation question.", "Mission card + front-office readiness signal map", "Evidence-first decision ladder visual", "Allowed vs not-allowed action board", "Behaviour cue card + pressure reflection prompt", "Safe wording bank for first guest response", "Guest trust and operations impact mini-map"]'::jsonb, '["Front-Office Arrival Readiness", "Evidence-Before-Action Principle", "L1 Role Boundary in Guest/Visitor Readiness", "Professional Readiness Mindset", "Pause Before Promise", "Service Value Awareness"]'::jsonb, 'At 3:30 PM, a tired guest is waiting near the front desk while the queue grows. The learner sees a reservation for Rohan Mehta, an early-arrival note, payment/readiness uncertainty, and a room that is not yet fully inspection-cleared. Before touching any check-in or access step, the learner must identify the course mission, L1 role boundary, tools, risks, and one open validation question.', 'null'::jsonb, FALSE, TRUE)
ON CONFLICT DO NOTHING;
INSERT INTO public."modules" ("id", "course_id", "module_no", "title", "description", "pressure_points", "user_confusion", "industry_challenge", "prerequisites", "what_youll_learn", "when_to_apply", "learning_content", "support", "knowledge", "module_problem_statement", "tools", "is_published", "is_active")
VALUES ('df2d80be-e296-5bda-901e-0869b8f2491e'::uuid, '0a010796-10c0-5287-b89a-6ab56bd71399'::uuid, 1, 'Case Intake & Role Boundary', 'Learner opens the arrival case, separates facts from assumptions, identifies available/missing records, and protects L1 authority while preparing intake.', NULL, NULL, NULL, NULL, NULL, NULL, '["Learn intake discipline and role-boundary language.", "Sort evidence cards into fact, assumption, missing, and question categories.", "Draft Case Intake Note for the Rohan Mehta case.", "Submit intake note with evidence references and safe clarification questions."]'::jsonb, '["Mark each item as confirmed, claim, missing, or risk in the Case Intake Note.", "Arrange the intake fields in evidence-first order.", "Extract five required fields from the mock PMS/front-office screen.", "Compare fact/assumption examples, suggest clearer wording after learner drafts the note, and challenge unsupported statements.", "Field-highlighted case file UI + intake grid", "Sequenced intake checklist", "Mock PMS screen with field highlights", "Listening cue card + claim vs confirmed tag", "Fact vs assumption sorting cards", "Safe greeting role-play prompt"]'::jsonb, '["Arrival Evidence Mapping", "Case Intake Sequencing", "PMS / Front-Office Field Recognition", "Active Listening for Arrival Evidence", "Assumption Control", "Calm Guest Greeting Under Pressure"]'::jsonb, 'The learner receives the first case file. Reservation card shows guest name Rohan Mehta, OTA source, today arrival, early arrival requested. Masked ID evidence shows Rohan M. The guest says payment is complete. PMS note says payment hold pending. Room board says Room 412 clean - not inspected. Learner must separate facts, assumptions, missing information, and role boundary.', 'null'::jsonb, FALSE, TRUE)
ON CONFLICT DO NOTHING;
INSERT INTO public."modules" ("id", "course_id", "module_no", "title", "description", "pressure_points", "user_confusion", "industry_challenge", "prerequisites", "what_youll_learn", "when_to_apply", "learning_content", "support", "knowledge", "module_problem_statement", "tools", "is_published", "is_active")
VALUES ('6549115e-08da-53bb-a2d8-4c1f40cda084'::uuid, '0a010796-10c0-5287-b89a-6ab56bd71399'::uuid, 2, 'Evidence / Requirement Validation', 'Learner validates whether reservation, identity, room-status, and payment/readiness evidence is complete, matching, missing, blocked, or requires supervisor review.', NULL, NULL, NULL, NULL, NULL, NULL, '["Learn evidence status categories and readiness blockers.", "Compare examples of match, minor variation, mismatch, missing, and hold.", "Complete checklist using Rohan case evidence.", "Submit checklist with evidence reasons and supervisor-review trigger."]'::jsonb, '["Label the reservation record as usable, incomplete, blocked, or needs review with reason.", "Classify the ID variation and write the safe next step.", "Rewrite one ID note in privacy-safe form.", "Review learner classification logic, ask for evidence source, and flag unsupported \"ready\" decisions after first checklist attempt.", "Reservation card with validation labels", "Match/minor variation/mismatch ladder", "Privacy-safe ID mockup", "Room-status board + payment-hold card", "Polite clarification wording bank", "Pause-vs-proceed decision card"]'::jsonb, '["Reservation Status Validation", "ID Matching and Mismatch Classification", "Privacy-Safe Guest Record Handling", "Room-Status and Payment Hold Validation", "Polite Clarification", "Confidence to Pause"]'::jsonb, 'The learner must validate whether the case evidence is complete and usable. Reservation name Rohan Mehta and ID name Rohan M. may be a minor variation, but payment hold pending and Room 412 clean-not-inspected are blockers. Learner must mark each signal as match, minor variation, mismatch, missing, or hold/blocker.', 'null'::jsonb, FALSE, TRUE)
ON CONFLICT DO NOTHING;
INSERT INTO public."modules" ("id", "course_id", "module_no", "title", "description", "pressure_points", "user_confusion", "industry_challenge", "prerequisites", "what_youll_learn", "when_to_apply", "learning_content", "support", "knowledge", "module_problem_statement", "tools", "is_published", "is_active")
VALUES ('b6606c1e-a0fd-505f-ba6c-d96e07150bba'::uuid, '0a010796-10c0-5287-b89a-6ab56bd71399'::uuid, 3, 'Guided Work Action or Handoff', 'Learner turns validated evidence into a role-safe recommendation or handoff without approving check-in or releasing access.', NULL, NULL, NULL, NULL, NULL, NULL, '["Learn role-safe handoff structure.", "Compare weak and strong handoff examples.", "Draft handoff note using validated evidence.", "Submit note with owner, blocker, evidence, recommendation, and boundary."]'::jsonb, '["Draft a handoff note with five required fields.", "Rewrite one unsafe approval phrase into L1-safe recommendation language.", "Select the likely owner path and note “SME validation required” where SOP owner is unknown.", "Ask whether note includes guest, evidence, blocker, owner, action not allowed, and safe next step; suggest clarity improvements only after draft.", "Weak vs strong handoff comparison", "Approval vs recommendation language board", "Owner-routing mini-map", "Controlled-access warning card", "Traceable handoff record template", "Accountability cue card"]'::jsonb, '["Role-Safe Handoff Note Design", "Recommendation vs Approval Language", "Owner Routing for Arrival Handoff", "Key/Access Handoff Boundary", "Traceable Service Handoff Record", "Accountability in Documentation"]'::jsonb, 'The learner has a completed validation checklist and must prepare a role-safe handoff note. The note must recommend supervisor review, show evidence, identify blockers, name owner, and state action not allowed for L1. Learner must not approve check-in or release key/access.', 'null'::jsonb, FALSE, TRUE)
ON CONFLICT DO NOTHING;
