VALUES ('75003941-b763-5c96-9fff-c47c6e00a5b5'::uuid, '0a010796-10c0-5287-b89a-6ab56bd71399'::uuid, 4, 'Exceptions, Blockers, Risks & Escalations', 'Learner identifies exceptions, blockers, dependency risks, wrong-owner routes, and pressure traps, then escalates with evidence and safe next step.', NULL, NULL, NULL, NULL, NULL, NULL, '["Learn escalation structure and owner mapping.", "Compare weak vs strong escalation under pressure.", "Write risk and escalation note for unresolved blockers.", "Submit escalation note with evidence, owner, consequence, and safe next step."]'::jsonb, '["Classify two blockers and link each to evidence.", "Map each blocker to owner/status: known owner or SME validation required.", "Draft a five-part supervisor note.", "Challenge the learner to name owner, risk, consequence, and safe next step; help rewrite unclear escalation after draft.", "Exception classification board", "Escalation matrix mockup", "Weak vs strong escalation note", "Conflict role-play activity", "Empathy-with-boundary wording card", "Pressure-to-safety decision simulation"]'::jsonb, '["Exception Classification", "Escalation Matrix Reading", "Supervisor Note Writing", "Composure During Conflict", "Empathy Without Overpromising", "Urgency Without Unsafe Release"]'::jsonb, 'The guest is still waiting, the queue has grown, housekeeping has not updated inspection status, and the payment hold is still visible. Learner must escalate the right blocker to the right owner with evidence and urgency, without letting pressure cause unsafe access or false reassurance.', 'null'::jsonb, FALSE, TRUE)
ON CONFLICT DO NOTHING;
