VALUES ('3d7514ef-3b3f-551d-b87d-72717114909d'::uuid, '0a010796-10c0-5287-b89a-6ab56bd71399'::uuid, 5, 'Quality, Communication & Closure', 'Learner checks whether L1 work is clear, complete, safe, and ready for review/closure while distinguishing completed work from unresolved risks.', NULL, NULL, NULL, NULL, NULL, NULL, '["Learn closure quality and communication clarity.", "Compare false vs responsible closure examples.", "Write closure report using previous artifacts.", "Submit closure report with pending risk, owner action, and portfolio proof."]'::jsonb, '["Classify closure status as L1 complete / owner pending / unresolved risk.", "Run a five-point quality check on the closure report.", "Write one remaining-risk statement for the closure report.", "Compare false vs responsible closure wording, flag missing remaining risk, and ask whether L1 has authority to close access decision.", "Closure status decision card", "Quality checklist overlay", "Remaining-risk communication card", "False vs responsible closure samples", "Self-review checklist + revision note", "Completion field checklist"]'::jsonb, '["Responsible Closure vs Resolution", "Quality Check for Arrival Readiness", "Remaining Risk Communication", "False Closure Detection", "Structured Self-Review", "Documentation Completeness"]'::jsonb, 'The learner must prepare closure status without pretending the case is solved. Supervisor review has been requested, but payment hold and room inspection may still be pending. Learner must separate completed L1 work from unresolved owner action and write truthful closure for handoff/review.', 'null'::jsonb, FALSE, TRUE)
ON CONFLICT DO NOTHING;
