VALUES ('635864f6-1f2c-5e4c-ae2e-06ffef18a321'::uuid, '0a010796-10c0-5287-b89a-6ab56bd71399'::uuid, 6, 'Portfolio, Transfer & Final Validation', 'Learner assembles evidence chain, defends decisions, applies same logic to a new visitor readiness case, and proves guided L1 capability.', NULL, NULL, NULL, NULL, NULL, NULL, '["Learn portfolio proof and transfer expectation.", "Compare guest and visitor readiness signals.", "Apply evidence-readiness method to visitor case.", "Submit final portfolio with artifact chain, transfer response, defense, and reflection."]'::jsonb, '["Create a portfolio index row for every artifact.", "Write two decision-trace lines linking evidence to action.", "Run a QA checklist and mark export-ready / needs revision.", "Prompt learner to identify transfer pattern, missing host confirmation, role boundary, and improvement evidence after learner submits first defense draft.", "Portfolio index template", "Decision traceability map", "Portfolio QA checklist + export preview", "Visitor case card + transfer challenge", "Interview story builder", "Feedback-to-revision tracker"]'::jsonb, '["Evidence Indexing", "Decision Traceability", "Portfolio QA and PDF Export", "Visitor Transfer Case Logic", "Interview Storytelling from Evidence", "Learning from Feedback"]'::jsonb, 'The learner assembles portfolio proof and then applies the same readiness method to a new visitor case: corporate visitor Anika Rao arrives for a meeting with guest/company contact, but host confirmation is missing and ID has a minor spelling variation. Learner must defend evidence logic and transfer role-safe escalation without treating visitor access like guest check-in approval.', 'null'::jsonb, FALSE, TRUE)
ON CONFLICT DO NOTHING;

